class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def run_cycle_start(values, pos):
    nodes = [ListNode(v) for v in values]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
    if pos >= 0:
        nodes[-1].next = nodes[pos]
    result = detect_cycle_start(nodes[0] if nodes else None)
    if result is None:
        return -1
    for i, node in enumerate(nodes):
        if node is result:
            return i
    raise ValueError("The returned node isn't one of the list's nodes.")

